css:
@font-face {
  font-family: "TH Sarabun Document";
  src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf") format("truetype");
  font-style: normal;
  font-weight: 400;
}

@page {
  size: A4;
  margin: 0;
}

html,
body {
  margin: 0 !important;
  padding: 0 !important;
}

/*
 * IMPORTANT FOR FRAPPE PDF:
 * Frappe reads the individual margin-* and page-size declarations from
 * .print-format and passes them to the PDF engine. Do not replace these with
 * only the shorthand `margin: 0`.
 */
.print-format {
  width: 210mm !important;
  min-width: 210mm !important;
  margin-top: 0mm !important;
  margin-right: 0mm !important;
  margin-bottom: 0mm !important;
  margin-left: 0mm !important;
  padding: 0 !important;
  page-size: A4;
}

.cd-po-root,
.cd-po-root * {
  box-sizing: border-box;
}

.cd-po-root {
  --cd-document-ink: #202020;
  --cd-document-border: #202020;
  --cd-document-surface: #f1f1f1;
  --cd-document-accent: #e2a2f5;

  width: 210mm;
  margin: 0;
  padding: 0;

  color: var(--cd-document-ink);
  background: #fff;

  font-family:
    "TH Sarabun Document",
    "Noto Sans Thai",
    "TH Sarabun New",
    "TH SarabunPSK",
    sans-serif;

  font-size: 4.22mm;
  font-weight: 400;
  line-height: 1;

  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

/* =========================================================
   FLOW TABLE — SOURCE OF TRUTH FOR PRINT / PDF

   There is only one item stream. The rendering engine decides where an item
   fits from its ACTUAL rendered height. No row is assigned to a page by Jinja.
   ========================================================= */

.po-flow-source {
  display: block;
  width: 210mm;
}

.page-flow-table {
  width: 210mm;
  margin: 0;
  padding: 0;

  border: 0;
  border-collapse: collapse;
  border-spacing: 0;
  table-layout: fixed;
}

.page-flow-table > thead {
  display: table-header-group;
}

.page-flow-table > tfoot {
  display: table-footer-group;
}

.page-flow-table > tbody {
  display: table-row-group;
}

.page-flow-table > thead > tr,
.page-flow-table > tfoot > tr,
.page-flow-table > tbody > tr {
  border: 0;
}

.page-flow-group-cell {
  width: 210mm;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  vertical-align: top !important;
}

.flow-item-fragment {
  page-break-inside: avoid !important;
  break-inside: avoid-page !important;
}

.flow-item-fragment > td {
  page-break-inside: avoid !important;
  break-inside: avoid-page !important;
}

.flow-item-table-wrap {
  width: 189.90mm;
  margin-left: 13.81mm;
  page-break-inside: avoid !important;
  break-inside: avoid-page !important;
}

/* =========================================================
   PAGE HEADER
   ========================================================= */

.document-header {
  position: relative;
  width: 210mm;
  height: 52.30mm;
  margin: 0;
  padding: 0;
}

.company-logo {
  position: absolute;
  left: 12.70mm;
  top: 18.56mm;
  width: 18.99mm;
  height: 7.25mm;
  object-fit: contain;
}

.company-name {
  position: absolute;
  left: 34.28mm;
  top: 13.62mm;
  width: 95mm;
  overflow: hidden;

  font-size: 6.20mm;
  font-weight: 700;
  line-height: 6.8mm;
  white-space: nowrap;
}

.lang-en .company-name {
  font-size: 5.65mm;
}

.company-address {
  position: absolute;
  left: 34.28mm;
  top: 22.82mm;
  width: 156mm;
  overflow: hidden;

  font-size: 4.22mm;
  line-height: 4.9mm;
  white-space: nowrap;
}

.lang-en .company-address {
  font-size: 4.05mm;
}

.company-contact {
  position: absolute;
  left: 34.28mm;
  top: 29.02mm;

  font-size: 4.22mm;
  line-height: 4.9mm;
  white-space: nowrap;
}

.company-tax-label,
.company-tax-value,
.company-branch {
  position: absolute;
  top: 35.63mm;

  font-size: 4.15mm;
  line-height: 5mm;
  white-space: nowrap;
}

.company-tax-label {
  left: 34.28mm;
}

.company-tax-value {
  left: 73.27mm;
}

.company-branch {
  left: 100.08mm;
}

.lang-en .company-tax-value {
  left: 52mm;
}

.lang-en .company-branch {
  left: 82mm;
}

.document-title,
.copy-title {
  position: absolute;
  left: 131.48mm;
  width: 59mm;

  display: -webkit-flex;
  display: flex;
  -webkit-align-items: center;
  align-items: center;
  -webkit-justify-content: center;
  justify-content: center;

  text-align: center;
  white-space: nowrap;
}

.document-title {
  top: 37.84mm;
  height: 8.20mm;

  padding: 0 2.5mm;
  border-radius: 6mm;
  background: var(--cd-document-accent);

  font-size: 6.25mm;
  font-weight: 700;
  line-height: 1;
}

.lang-en .document-title {
  font-size: 5.70mm;
}

.copy-title {
  top: 47.05mm;
  height: 5.50mm;

  font-size: 4.60mm;
  font-weight: 700;
  line-height: 1;
}

.document-main-head,
.document-main-foot,
.preview-document-main {
  width: 189.90mm;
  margin-left: 13.81mm;
}

.info-box {
  width: 100%;
  border: 0.24mm solid var(--cd-document-border);
  border-radius: 2.18mm;
  background: #fff;
}

/* =========================================================
   DOCUMENT META
   ========================================================= */

.document-meta-box {
  padding: 2.75mm 3.60mm 2.55mm;
}

.meta-grid {
  width: 100%;

  display: -webkit-flex;
  display: flex;
  -webkit-flex-wrap: wrap;
  flex-wrap: wrap;

  margin: -1.00mm -2.10mm;
}

.meta-item {
  min-width: 0;
  width: 25%;

  display: -webkit-flex;
  display: flex;
  -webkit-align-items: center;
  align-items: center;

  padding: 1.00mm 2.10mm;
}

.meta-label {
  -webkit-flex: 0 0 auto;
  flex: 0 0 auto;
  min-width: 0;
  margin-right: 1.80mm;

  font-size: 4.10mm;
  font-weight: 700;
  line-height: 4.65mm;
  white-space: nowrap;
}

.meta-value {
  -webkit-flex: 1 1 auto;
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;

  font-size: 4.10mm;
  font-weight: 400;
  line-height: 4.65mm;
  white-space: nowrap;
  text-overflow: clip;
}

.meta-item:nth-child(5) .meta-value,
.meta-item:nth-child(7) .meta-value {
  white-space: normal;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.meta-value-strong {
  font-size: 4.45mm;
  font-weight: 700;
}

.credit-pill {
  display: inline-block;
  min-width: 17.80mm;
  padding: 0.25mm 2.15mm 0.45mm;

  border: 0.24mm solid var(--cd-document-border);
  border-radius: 4mm;

  line-height: 4.10mm;
  text-align: center;
  white-space: nowrap;
}

/* =========================================================
   SUPPLIER / SHIP TO / CONTACT
   ========================================================= */

.address-contact-box {
  margin-top: 2.40mm;
  padding: 3.00mm 3.60mm 3.20mm;
}

.address-grid {
  width: 100%;

  display: -webkit-flex;
  display: flex;
  -webkit-align-items: stretch;
  align-items: stretch;
}

.supplier-section,
.shipto-section {
  -webkit-flex: 1.35 1 0;
  flex: 1.35 1 0;
}

.contact-section {
  -webkit-flex: 0.80 1 0;
  flex: 0.80 1 0;
}

.address-section {
  min-width: 0;
  height: auto;
  padding: 0 3.60mm;
  overflow: visible;
}

.address-section:first-child {
  padding-left: 0;
}

.address-section:last-child {
  padding-right: 0;
}

.address-section + .address-section {
  border-left: 0.24mm solid var(--cd-document-border);
}

.section-heading {
  display: -webkit-flex;
  display: flex;
  -webkit-flex-wrap: wrap;
  flex-wrap: wrap;
  -webkit-align-items: baseline;
  align-items: baseline;

  margin: 0 0 1.20mm;
}

.section-heading > * + * {
  margin-left: 1.80mm;
}

.section-title {
  font-size: 4.22mm;
  font-weight: 700;
  line-height: 4.80mm;
  white-space: nowrap;
}

.supplier-code {
  font-size: 4.10mm;
  font-weight: 400;
  line-height: 4.80mm;
  white-space: nowrap;
}

.section-primary {
  margin: 0 0 0.80mm;

  font-size: 4.22mm;
  font-weight: 400;
  line-height: 4.45mm;

  white-space: normal;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.section-content {
  min-width: 0;
  margin: 0;
  padding: 0;

  font-size: 4.10mm;
  font-weight: 400;
  line-height: 4.20mm;

  white-space: normal;
  overflow: visible;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.address-display,
.contact-display {
  height: auto;
  min-height: 0;
  max-height: none;
}

.address-display p,
.contact-display p {
  margin: 0 !important;
  padding: 0 !important;
  font: inherit !important;
  line-height: inherit !important;
}

.address-display br,
.contact-display br {
  display: block !important;
}

/* =========================================================
   PRODUCT HEADER
   ========================================================= */

.product-head-wrap {
  width: 100%;
  margin-top: 3.20mm;
}

.product-head {
  width: 100%;
  height: 8.64mm;

  display: -webkit-flex;
  display: flex;

  border: 0.24mm solid var(--cd-document-border);
  border-radius: 2.18mm 2.18mm 0 0;
  background: var(--cd-document-surface);

  font-weight: 700;
  overflow: hidden;
}

.head-cell {
  min-width: 0;
  height: 8.16mm;

  display: -webkit-flex;
  display: flex;
  -webkit-align-items: center;
  align-items: center;
  -webkit-justify-content: center;
  justify-content: center;

  padding: 0.35mm 0.55mm;
  border-right: 0.24mm solid var(--cd-document-border);

  font-size: 4.05mm;
  line-height: 4mm;
  text-align: center;
  overflow: hidden;
}

.product-head .col-no {
  -webkit-flex: 0 0 9.50mm;
  flex: 0 0 9.50mm;
}

.product-head .col-item-code {
  -webkit-flex: 0 0 24mm;
  flex: 0 0 24mm;
}

.product-head .col-mat-code {
  -webkit-flex: 0 0 24mm;
  flex: 0 0 24mm;
}

.product-head .col-description {
  -webkit-flex: 0 0 46.40mm;
  flex: 0 0 46.40mm;
}

.product-head .col-quantity {
  -webkit-flex: 0 0 18mm;
  flex: 0 0 18mm;
}

.product-head .col-uom {
  -webkit-flex: 0 0 17mm;
  flex: 0 0 17mm;
}

.product-head .col-unit-price {
  -webkit-flex: 0 0 25.50mm;
  flex: 0 0 25.50mm;
}

.product-head .col-amount {
  -webkit-flex: 0 0 25.50mm;
  flex: 0 0 25.50mm;
}

.head-cell:last-child {
  border-right: 0;
}

/* =========================================================
   ITEM ROWS
   ========================================================= */

.item-lines {
  width: 100%;
  margin: 0;
  padding: 0;

  border: 0;
  border-collapse: separate;
  border-spacing: 0;
  table-layout: fixed;

  background: transparent;
}

.item-lines col.col-no {
  width: 9.50mm;
}

.item-lines col.col-item-code {
  width: 24mm;
}

.item-lines col.col-mat-code {
  width: 24mm;
}

.item-lines col.col-description {
  width: 46.40mm;
}

.item-lines col.col-quantity {
  width: 18mm;
}

.item-lines col.col-uom {
  width: 17mm;
}

.item-lines col.col-unit-price {
  width: 25.50mm;
}

.item-lines col.col-amount {
  width: 25.50mm;
}

.item-lines .item-row,
.item-lines .item-row td {
  page-break-inside: avoid !important;
  break-inside: avoid-page !important;
}

.item-lines td {
  margin: 0;

  border: 0 !important;
  border-right: 0.24mm solid var(--cd-document-border) !important;

  font-size: 4.10mm;
  font-weight: 400;
  line-height: 4.25mm;

  vertical-align: top !important;
}

.item-lines td:last-child {
  border-right: 0 !important;
}

.item-lines .item-row td {
  height: 8.50mm;
  padding: 2.00mm 1.15mm 0.65mm;
}

.item-lines .cell-no {
  text-align: center;
}

.item-lines .cell-item-code,
.item-lines .cell-mat-code {
  padding-left: 1.15mm;
  padding-right: 0.70mm;
  white-space: nowrap;
}

.item-lines .cell-description {
  padding-left: 1.35mm;
  padding-right: 1mm;
  white-space: normal;
  overflow: visible;
  overflow-wrap: anywhere;
  word-break: normal;
}

.item-lines .cell-quantity {
  text-align: right;
  white-space: nowrap;
}

.item-lines .cell-uom {
  text-align: center;
  white-space: nowrap;
}

.item-lines .cell-money {
  text-align: right;
  white-space: nowrap;
}

/* Each flow row contributes its real height. Never clip it. */
.flow-item-table-wrap {
  border-left: 0.24mm solid var(--cd-document-border);
  border-right: 0.24mm solid var(--cd-document-border);
  overflow: visible;
}

.flow-item-table {
  width: 100%;
  height: auto;
}

/* =========================================================
   SUMMARY + TOTAL
   ========================================================= */

.purchase-footer {
  width: 100%;
  border-left: 0.24mm solid var(--cd-document-border);
  border-right: 0.24mm solid var(--cd-document-border);
  background: #fff;
}

.summary-area {
  position: relative;
  width: 100%;
  height: 27.66mm;

  border-top: 0.24mm solid var(--cd-document-border);
  border-bottom: 0.24mm solid var(--cd-document-border);
}

.remark-label {
  position: absolute;
  left: 4.75mm;
  top: 3.20mm;

  font-size: 4.22mm;
  font-weight: 700;
  line-height: 5mm;
}

.remark-value {
  position: absolute;
  left: 4.75mm;
  top: 9.20mm;

  width: 86mm;
  height: 15mm;
  overflow: hidden;

  font-size: 4.10mm;
  line-height: 4.45mm;
}

.summary-labels {
  position: absolute;
  left: 101mm;
  top: 2.20mm;
  width: 51mm;
}

.summary-label {
  position: relative;
  height: 6.05mm;

  font-size: 4.10mm;
  font-weight: 700;
  line-height: 5mm;
}

.vat-rate {
  position: absolute;
  left: 140mm;
  top: 20.35mm;
  width: 21mm;

  font-size: 4.15mm;
  line-height: 5mm;
  text-align: center;
  white-space: nowrap;
}

.summary-values {
  position: absolute;
  left: 164.40mm;
  top: 0;

  width: 25.50mm;
  height: 27.66mm;
  padding-top: 2.20mm;
  padding-right: 1.55mm;

  border-left: 0.24mm solid var(--cd-document-border);

  font-size: 4.15mm;
  line-height: 5mm;
  text-align: right;
}

.summary-values > div {
  height: 6.05mm;
}

.total-row {
  position: relative;
  width: 100%;
  height: 9.59mm;

  border-bottom: 0.24mm solid var(--cd-document-border);
}

.amount-in-words {
  position: absolute;
  left: 4.75mm;
  top: 2.55mm;

  width: 101mm;
  overflow: hidden;

  font-size: 4.05mm;
  line-height: 5mm;
  white-space: nowrap;
}

.total-label {
  position: absolute;
  left: 109mm;
  top: 2.15mm;
  width: 50mm;

  font-size: 4.10mm;
  font-weight: 700;
  line-height: 5mm;
  text-align: center;
}

.total-value {
  position: absolute;
  left: 164.40mm;
  top: 0;

  width: 25.50mm;
  height: 9.35mm;
  padding-top: 2.55mm;
  padding-right: 1.55mm;

  border-left: 0.24mm solid var(--cd-document-border);

  font-size: 4.22mm;
  font-weight: 700;
  line-height: 5mm;
  text-align: right;
}

/* =========================================================
   APPROVAL
   ========================================================= */

.approval-box {
  position: relative;
  width: 100%;
  height: 27.17mm;
  overflow: hidden;

  border: 0.24mm solid var(--cd-document-border);
  border-top: 0;
  border-radius: 0 0 2.18mm 2.18mm;
  background: #fff;
}

.approval-left,
.approval-right {
  position: absolute;
  top: 0;
  height: 100%;
}

.approval-left {
  left: 0;
  width: 96.19mm;
  border-right: 0.24mm solid var(--cd-document-border);
}

.approval-right {
  left: 96.19mm;
  width: 93.71mm;
}

.ordered-by-name {
  position: absolute;
  left: 12mm;
  top: 12.70mm;
  width: 48mm;
  overflow: hidden;

  font-size: 4.10mm;
  font-weight: 400;
  line-height: 4.70mm;
  text-align: center;
  white-space: nowrap;
}

.order-signature-line {
  position: absolute;
  left: 16.55mm;
  top: 18.36mm;
  width: 38.20mm;
  border-top: 0.24mm solid var(--cd-document-border);
}

.order-date-line {
  position: absolute;
  left: 56.32mm;
  top: 16.62mm;
  width: 25mm;

  font-size: 4.05mm;
  line-height: 5mm;
  text-align: center;
  white-space: nowrap;
}

.order-signature-caption {
  position: absolute;
  left: 12mm;
  top: 21.15mm;
  width: 48mm;

  font-size: 4.10mm;
  line-height: 5mm;
  text-align: center;
  white-space: nowrap;
}

.order-date-caption {
  position: absolute;
  left: 58.85mm;
  top: 21.15mm;
  width: 20mm;

  font-size: 4.10mm;
  line-height: 5mm;
  text-align: center;
  white-space: nowrap;
}

.on-behalf {
  position: absolute;
  left: 20.25mm;
  top: 2.50mm;

  font-size: 4.05mm;
  line-height: 4.3mm;
}

.signature-company {
  position: absolute;
  left: 12mm;
  top: 5.70mm;
  width: 70mm;
  overflow: hidden;

  font-size: 4.15mm;
  font-weight: 700;
  line-height: 5mm;
  text-align: center;
  white-space: nowrap;
}

.authorized-line {
  position: absolute;
  left: 20.32mm;
  top: 18.70mm;
  width: 46.05mm;
  border-top: 0.24mm solid var(--cd-document-border);
}

.authorized-caption {
  position: absolute;
  left: 15mm;
  top: 21.55mm;
  width: 57mm;

  font-size: 4.10mm;
  line-height: 5mm;
  text-align: center;
  white-space: nowrap;
}

/* =========================================================
   BROWSER PREVIEW — EXPLICIT 210 x 297 mm PAGES
   ========================================================= */

.po-preview-pages,
.preview-prototype {
  display: none;
}

/* Make generated pages measurable without flashing them on screen. */
.cd-po-root.preview-measuring .po-preview-pages {
  display: block;
  position: absolute;
  left: -10000px;
  top: 0;
  visibility: hidden;
}

.cd-po-root.preview-ready .po-flow-source {
  display: none;
}

.cd-po-root.preview-ready .po-preview-pages {
  display: block;
}

.cd-po.preview-page,
.cd-po.preview-prototype {
  position: relative;
  width: 210mm;
  height: 297mm;
  min-height: 297mm;
  max-height: 297mm;
  margin: 0;
  padding: 0;
  overflow: hidden;

  color: var(--cd-document-ink);
  background: #fff;

  font-family:
    "TH Sarabun Document",
    "Noto Sans Thai",
    "TH Sarabun New",
    "TH SarabunPSK",
    sans-serif;

  font-size: 4.22mm;
  font-weight: 400;
  line-height: 1;

  page-break-after: always;
  break-after: page;

  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.cd-po.preview-page.last-page {
  page-break-after: auto;
  break-after: auto;
}

.preview-document-main {
  margin-top: 0;
}

.preview-purchase-grid {
  width: 100%;
  margin: 0;
  padding: 0;
}

.preview-product-body {
  position: relative;
  width: 100%;
  height: 104mm;
  min-height: 104mm;
  max-height: 104mm;
  overflow: hidden;

  border-left: 0.24mm solid var(--cd-document-border);
  border-right: 0.24mm solid var(--cd-document-border);
  background: #fff;
}

.preview-item-lines {
  width: 100%;
  height: 100%;
  min-height: 100%;
}

.preview-item-lines.measuring {
  height: auto !important;
  min-height: 0 !important;
}

.preview-item-lines .fill-row {
  height: 100%;
}

.preview-item-lines .fill-row td {
  height: 100%;
  padding: 0 !important;
  border-right: 0.24mm solid var(--cd-document-border) !important;
}

.preview-item-lines .fill-row td:last-child {
  border-right: 0 !important;
}

/* Keep the preview footer attached to the fixed 104 mm item body. */
.preview-document-main > .document-main-foot {
  width: 100%;
  margin-left: 0;
}

/* =========================================================
   PRINT SAFETY
   ========================================================= */

@media print {
  .po-preview-pages,
  .preview-prototype {
    display: none !important;
  }

  .cd-po-root.preview-ready .po-flow-source,
  .po-flow-source {
    display: block !important;
  }

  .page-flow-table > thead {
    display: table-header-group !important;
  }

  .page-flow-table > tfoot {
    display: table-footer-group !important;
  }

  .flow-item-fragment,
  .flow-item-fragment > td,
  .flow-item-table-wrap,
  .item-row,
  .item-row > td {
    page-break-inside: avoid !important;
    break-inside: avoid-page !important;
  }
}


/* =========================================================
   V4 MANUAL A4 PAGES - SINGLE PATH FOR PREVIEW AND PDF
   ========================================================= */
.manual-page {
  display: block !important;
}

.manual-item-lines .item-row,
.manual-item-lines .item-row > td {
  page-break-inside: avoid !important;
  break-inside: avoid !important;
}

/* The visible item table is always exactly 104 mm high. */
.manual-page .preview-product-body {
  height: 104mm !important;
  min-height: 104mm !important;
  max-height: 104mm !important;
  overflow: hidden !important;
}

/* Real item rows occupy only the safe content budget; filler extends the
   column borders to the physical bottom of the 104 mm item area. */
.manual-page .manual-item-lines {
  width: 100%;
  height: 100%;
  min-height: 100%;
  table-layout: fixed;
}

.manual-page .manual-item-lines .fill-row {
  height: 100%;
}

.manual-page .manual-item-lines .fill-row td {
  height: 100%;
  padding: 0 !important;
  border-right: 0.24mm solid var(--cd-document-border) !important;
}

.manual-page .manual-item-lines .fill-row td:last-child {
  border-right: 0 !important;
}

@media print {
  .manual-page {
    display: block !important;
    page-break-after: always !important;
    break-after: page !important;
  }

  .manual-page.last-page {
    page-break-after: auto !important;
    break-after: auto !important;
  }
}

html:
{#
  ERPNext Custom Print Format: Purchase Order
  DocType: Purchase Order

  Pagination strategy (v3):
  - NO batch(10)
  - NO Jinja height estimation
  - Browser preview: actual rendered row heights are measured after fonts/images load.
  - PDF / print fallback: one flowing table with repeating THEAD/TFOOT and
    page-break-inside: avoid on each item row. This prevents an item from
    being consumed by one page and then clipped by overflow:hidden.
#}

{{ register_print(doc) }}

{# =========================================================
   LANGUAGE
   ========================================================= #}
{% set requested_lang = frappe.form_dict.get("_lang") if frappe.form_dict else "" %}
{% set print_lang = (requested_lang or doc.get("language") or frappe.local.lang or "th") | lower %}
{% set is_en = print_lang[:2] == "en" %}

{% macro t(th, en) -%}
  {{ en if is_en else th }}
{%- endmacro %}

{% macro print_date(value) -%}
  {% if value %}
    {% if is_en %}
      {{ frappe.utils.formatdate(value, "dd-MM-yyyy") }}
    {% else %}
      {{ format_date(value) }}
    {% endif %}
  {% endif %}
{%- endmacro %}


{# =========================================================
   DOCUMENT DATA
   ========================================================= #}
{% set first_item = doc.items[0] if doc.items else none %}
{% set required_date = doc.schedule_date or (first_item.schedule_date if first_item else none) %}
{% set delivery_by = doc.get("custom_delivery_by") or doc.get("shipping_rule") or "" %}
{% set eta_date = doc.get("eta") or doc.get("custom_eta") or required_date %}
{% set incoterm = doc.incoterm or "" %}
{% set currency = doc.currency or "" %}

{% if is_en %}
  {% set company_name = "Connect Diagnostics Co., Ltd." %}
  {% set company_address = "1/57-58 Venice Di Iris, Soi Watcharaphon 2/7, Tha Raeng, Bang Khen, Bangkok 10220, Thailand" %}
  {% set company_tax_label = "Tax ID" %}
  {% set company_branch = "Head Office" %}
{% else %}
  {% set company_name = "บริษัท คอนเนคไดแอกโนสติกส์ จำกัด" %}
  {% set company_address = "1/57-58 เวนิส ดี ไอริส ซอยวัชรพล 2/7 แขวงท่าแร้ง เขตบางเขน กรุงเทพฯ 10220" %}
  {% set company_tax_label = "เลขประจำตัวผู้เสียภาษี" %}
  {% set company_branch = "สำนักงานใหญ่" %}
{% endif %}

{% set supplier_name = doc.supplier_name or doc.supplier or "" %}
{% set supplier_address = doc.address_display or "" %}
{% set ship_to_address = doc.shipping_address_display or "" %}
{% set supplier_contact = doc.contact_display or doc.contact_person or "" %}
{% set remark_text = doc.terms or doc.get("remarks") or "" %}
{% set ordered_by_name = frappe.get_fullname(doc.owner) if doc.owner else "" %}


{# =========================================================
   CREDIT TERMS
   ========================================================= #}
{% set credit_days = (doc.payment_schedule[0].get("credit_days") or 0) if doc.payment_schedule else 0 %}

{% if credit_days %}
  {% set credit_text = (credit_days ~ " Days") if is_en else (credit_days ~ " วัน") %}
{% elif doc.payment_terms_template %}
  {% set credit_text = doc.payment_terms_template %}
{% else %}
  {% set credit_text = "Cash" if is_en else "เงินสด" %}
{% endif %}


{# =========================================================
   TOTALS
   ========================================================= #}
{% set gross_amount = (doc.total or 0) | float %}
{% set net_total = (doc.net_total if doc.net_total is not none else gross_amount) | float %}
{% set item_discount = gross_amount - net_total %}
{% set additional_discount = (doc.discount_amount or 0) | float %}
{% set discount_amount = item_discount + additional_discount %}
{% set after_discount = gross_amount - discount_amount %}
{% set vat_rate = (doc.taxes[0].rate or 0) if doc.taxes else 0 %}
{% set vat_amount = (doc.total_taxes_and_charges or 0) | float %}

{% if is_en %}
  {% set amount_in_words = doc.in_words or "" %}
{% else %}
  {% set amount_in_words = number_to_thai_currency(doc.grand_total or 0, doc.currency) %}
{% endif %}


{# =========================================================
   REUSABLE ITEM TABLE COLUMNS
   ========================================================= #}
{% macro item_colgroup() -%}
  <colgroup>
    <col class="col-no">
    <col class="col-item-code">
    <col class="col-mat-code">
    <col class="col-description">
    <col class="col-quantity">
    <col class="col-uom">
    <col class="col-unit-price">
    <col class="col-amount">
  </colgroup>
{%- endmacro %}

{% macro product_head() -%}
  <div class="product-head">
    <div class="head-cell col-no">{{ t("ลำดับ", "No.") }}</div>
    <div class="head-cell col-item-code">{{ t("รหัสสินค้า", "Item Code") }}</div>
    <div class="head-cell col-mat-code">{{ t("รหัสผู้จำหน่าย", "Mat. Code") }}</div>
    <div class="head-cell col-description">{{ t("รายละเอียด", "Description") }}</div>
    <div class="head-cell col-quantity">{{ t("จำนวน", "QTY") }}</div>
    <div class="head-cell col-uom">{{ t("หน่วย", "UOM") }}</div>
    <div class="head-cell col-unit-price">{{ t("หน่วยละ", "Unit Price") }}</div>
    <div class="head-cell col-amount">{{ t("จำนวนเงิน", "Amount") }}</div>
  </div>
{%- endmacro %}

{% macro item_row(row) -%}
  {% set item_description = row.item_name or row.description or "" %}
  <tr class="item-row" data-item-idx="{{ row.idx }}">
    <td class="cell-no">{{ row.idx }}</td>
    <td class="cell-item-code">{{ row.item_code or "" }}</td>
    <td class="cell-mat-code">{{ row.supplier_part_no or "" }}</td>
    <td class="cell-description">{{ item_description | striptags }}</td>
    <td class="cell-quantity">{{ format_money(row.qty) }}</td>
    <td class="cell-uom">{{ row.uom or row.stock_uom or "" }}</td>
    <td class="cell-money">{{ format_money(row.price_list_rate or row.rate) }}</td>
    <td class="cell-money">{{ format_money(row.amount) }}</td>
  </tr>
{%- endmacro %}


{# =========================================================
   FULL REPEATED PAGE HEADER CONTENT
   ========================================================= #}
{% macro page_header_content() -%}
  <header class="document-header">
    <img
      class="company-logo"
      src="/assets/connect_diagnostics_core/images/cd_logo_v2.jpg"
      alt="Connect Diagnostics"
    >

    <div class="company-name">{{ company_name }}</div>
    <div class="company-address">{{ company_address }}</div>
    <div class="company-contact">02-3470109&nbsp;&nbsp;&nbsp; www.connectdiagnostics.com</div>

    <div class="company-tax-label">{{ company_tax_label }}</div>
    <div class="company-tax-value">0105551058581</div>
    <div class="company-branch">{{ company_branch }}</div>

    <div class="document-title">{{ t("ใบสั่งซื้อ", "Purchase Order") }}</div>
    <div class="copy-title">{{ t("ต้นฉบับ", "Original") }}</div>
  </header>

  <div class="document-main-head">
    <section class="info-box document-meta-box">
      <div class="meta-grid">
        <div class="meta-item meta-po-number">
          <div class="meta-label">{{ t("เลขที่ใบสั่งซื้อ", "P/O No.") }}</div>
          <div class="meta-value meta-value-strong">{{ doc.name }}</div>
        </div>

        <div class="meta-item">
          <div class="meta-label">{{ t("วันที่", "Date") }}</div>
          <div class="meta-value">{{ print_date(doc.transaction_date) }}</div>
        </div>

        <div class="meta-item">
          <div class="meta-label">{{ t("วันที่รับของ", "Required Date") }}</div>
          <div class="meta-value">{{ print_date(required_date) }}</div>
        </div>

        <div class="meta-item">
          <div class="meta-label">{{ t("เครดิต", "Credit") }}</div>
          <div class="meta-value"><span class="credit-pill">{{ credit_text }}</span></div>
        </div>

        <div class="meta-item">
          <div class="meta-label">{{ t("ขนส่งโดย", "Delivery By") }}</div>
          <div class="meta-value">{{ delivery_by }}</div>
        </div>

        <div class="meta-item">
          <div class="meta-label">{{ t("กำหนดถึง", "ETA") }}</div>
          <div class="meta-value">{{ print_date(eta_date) }}</div>
        </div>

        <div class="meta-item">
          <div class="meta-label">{{ t("เงื่อนไขการส่งมอบ", "Incoterm") }}</div>
          <div class="meta-value">{{ incoterm }}</div>
        </div>

        <div class="meta-item">
          <div class="meta-label">{{ t("สกุลเงิน", "Currency") }}</div>
          <div class="meta-value">{{ currency }}</div>
        </div>
      </div>
    </section>

    <section class="info-box address-contact-box">
      <div class="address-grid">
        <section class="address-section supplier-section">
          <div class="section-heading">
            <span class="section-title">{{ t("ผู้จำหน่าย", "Supplier") }}</span>
            <span class="supplier-code">{{ doc.supplier or "" }}</span>
          </div>
          <div class="section-primary">{{ supplier_name }}</div>
          <div class="section-content address-display">{{ supplier_address | safe }}</div>
        </section>

        <section class="address-section shipto-section">
          <div class="section-heading">
            <span class="section-title">{{ t("ส่งไปที่", "Ship To") }}</span>
          </div>
          <div class="section-content address-display">{{ ship_to_address | safe }}</div>
        </section>

        <section class="address-section contact-section">
          <div class="section-heading">
            <span class="section-title">{{ t("ติดต่อ", "Contact") }}</span>
          </div>
          <div class="section-content contact-display">{{ supplier_contact | safe }}</div>
        </section>
      </div>
    </section>

    <div class="product-head-wrap">
      {{ product_head() }}
    </div>
  </div>
{%- endmacro %}


{# =========================================================
   FULL REPEATED PAGE FOOTER CONTENT
   ========================================================= #}
{% macro page_footer_content() -%}
  <div class="document-main-foot">
    <section class="purchase-footer">
      <div class="summary-area">
        <div class="remark-label">{{ t("หมายเหตุ", "Remark") }}</div>
        <div class="remark-value">{{ remark_text | striptags }}</div>

        <div class="summary-labels">
          <div class="summary-label">{{ t("รวมเป็นเงิน", "Gross Amount") }}</div>
          <div class="summary-label">{{ t("หักส่วนลด", "Less Discount") }}</div>
          <div class="summary-label">{{ t("ยอดหลังหักส่วนลด", "After Discount") }}</div>
          <div class="summary-label">{{ t("ภาษีมูลค่าเพิ่ม", "VAT") }}</div>
        </div>

        <div class="vat-rate">{{ format_money(vat_rate) }}&nbsp;%</div>

        <div class="summary-values">
          <div>{{ format_money(gross_amount) }}</div>
          <div>{{ format_money(discount_amount) }}</div>
          <div>{{ format_money(after_discount) }}</div>
          <div>{{ format_money(vat_amount) }}</div>
        </div>
      </div>

      <div class="total-row">
        <div class="amount-in-words">({{ amount_in_words }}).</div>
        <div class="total-label">{{ t("จำนวนเงินรวมทั้งสิ้น", "Net Amount") }}</div>
        <div class="total-value">{{ format_money(doc.grand_total) }}</div>
      </div>
    </section>

    <footer class="approval-box">
      <div class="approval-left">
        <div class="ordered-by-name">{{ ordered_by_name }}</div>
        <div class="order-signature-line"></div>
        <div class="order-date-line">____/____/____</div>
        <div class="order-signature-caption">{{ t("ผู้สั่งซื้อสินค้า", "Ordered By") }}</div>
        <div class="order-date-caption">{{ t("วันที่", "Date") }}</div>
      </div>

      <div class="approval-right">
        <div class="on-behalf">{{ t("ในนาม", "On behalf of") }}</div>
        <div class="signature-company">{{ company_name }}</div>
        <div class="authorized-line"></div>
        <div class="authorized-caption">{{ t("ผู้รับมอบอำนาจ", "Authorized Signature") }}</div>
      </div>
    </footer>
  </div>
{%- endmacro %}



{# =========================================================
   SERVER-SIDE PAGINATION (NO JAVASCRIPT)

   ERPNext's Jinja render does not have access to DOM pixel heights.
   Therefore one explicit A4 page is built at a time and each item is
   charged against a height budget derived from the SAME typography used
   by the printed row. This is content-based pagination, not item-count
   pagination. A safety reserve prevents wkhtmltopdf/font-wrap variance
   from clipping the last row.
   ========================================================= #}
{% set ITEM_BODY_HEIGHT_MM = 104.0 %}
{% set ITEM_USABLE_HEIGHT_MM = 96.0 %}
{% set DESC_CHARS_PER_LINE = 22 %}
{% set CODE_CHARS_PER_LINE = 12 %}
{% set MAT_CHARS_PER_LINE = 12 %}
{% set UOM_CHARS_PER_LINE = 8 %}
{% set ROW_LINE_HEIGHT_MM = 4.25 %}
{% set ROW_VERTICAL_PADDING_MM = 2.65 %}
{% set ROW_MIN_HEIGHT_MM = 8.50 %}

{% set pg = namespace(pages=[], current=[], used_mm=0.0) %}

{% for row in (doc.items or []) %}
  {% set item_description = (row.item_name or row.description or "") | striptags | trim %}
  {% set item_code_text = (row.item_code or "") | trim %}
  {% set mat_code_text = (row.supplier_part_no or "") | trim %}
  {% set uom_text = (row.uom or row.stock_uom or "") | trim %}

  {# Conservative wrapped-line estimate for each potentially wrapping cell. #}
  {% set desc_lines = ((item_description | length) + DESC_CHARS_PER_LINE - 1) // DESC_CHARS_PER_LINE if item_description else 1 %}
  {% set code_lines = ((item_code_text | length) + CODE_CHARS_PER_LINE - 1) // CODE_CHARS_PER_LINE if item_code_text else 1 %}
  {% set mat_lines = ((mat_code_text | length) + MAT_CHARS_PER_LINE - 1) // MAT_CHARS_PER_LINE if mat_code_text else 1 %}
  {% set uom_lines = ((uom_text | length) + UOM_CHARS_PER_LINE - 1) // UOM_CHARS_PER_LINE if uom_text else 1 %}

  {% set visual_lines = desc_lines %}
  {% if code_lines > visual_lines %}{% set visual_lines = code_lines %}{% endif %}
  {% if mat_lines > visual_lines %}{% set visual_lines = mat_lines %}{% endif %}
  {% if uom_lines > visual_lines %}{% set visual_lines = uom_lines %}{% endif %}

  {% set calculated_height = (visual_lines * ROW_LINE_HEIGHT_MM) + ROW_VERTICAL_PADDING_MM %}
  {% set row_height_mm = ROW_MIN_HEIGHT_MM if calculated_height < ROW_MIN_HEIGHT_MM else calculated_height %}

  {# Whole-row move: never consume an item on the old page if it does not fit. #}
  {% if pg.current and (pg.used_mm + row_height_mm) > ITEM_USABLE_HEIGHT_MM %}
    {% set _ = pg.pages.append(pg.current) %}
    {% set pg.current = [] %}
    {% set pg.used_mm = 0.0 %}
  {% endif %}

  {% set _ = pg.current.append({"row": row, "height_mm": row_height_mm}) %}
  {% set pg.used_mm = pg.used_mm + row_height_mm %}
{% endfor %}

{% if pg.current %}
  {% set _ = pg.pages.append(pg.current) %}
{% endif %}
{% if not pg.pages %}
  {% set _ = pg.pages.append([]) %}
{% endif %}

<div id="cd-po-root" class="cd-po-root{% if is_en %} lang-en{% else %} lang-th{% endif %}">
  {% for page_items in pg.pages %}
    <div class="cd-po preview-page manual-page{% if loop.last %} last-page{% endif %}">
      {{ page_header_content() }}

      <div class="preview-document-main">
        <section class="preview-purchase-grid">
          <div class="preview-product-body">
            <table class="item-lines preview-item-lines manual-item-lines">
              {{ item_colgroup() }}
              <tbody>
                {% for entry in page_items %}
                  {% set row = entry.row %}
                  {% set item_description = row.item_name or row.description or "" %}
                  <tr class="item-row" data-item-idx="{{ row.idx }}" style="height: {{ entry.height_mm }}mm;">
                    <td class="cell-no">{{ row.idx }}</td>
                    <td class="cell-item-code">{{ row.item_code or "" }}</td>
                    <td class="cell-mat-code">{{ row.supplier_part_no or "" }}</td>
                    <td class="cell-description">{{ item_description | striptags }}</td>
                    <td class="cell-quantity">{{ format_money(row.qty) }}</td>
                    <td class="cell-uom">{{ row.uom or row.stock_uom or "" }}</td>
                    <td class="cell-money">{{ format_money(row.price_list_rate or row.rate) }}</td>
                    <td class="cell-money">{{ format_money(row.amount) }}</td>
                  </tr>
                {% endfor %}

                <tr class="fill-row">
                  <td></td><td></td><td></td><td></td>
                  <td></td><td></td><td></td><td></td>
                </tr>
              </tbody>
            </table>
          </div>
        </section>

        {{ page_footer_content() }}
      </div>
    </div>
  {% endfor %}
</div>
